"""Dependency-free Admin UI served by the authenticated booking application."""

PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow"><title>Calendar Admin | Best Driving School</title>
<style>
:root{color-scheme:light;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;--navy:#0b2746;--blue:#1769aa;--blue2:#0f568e;--ink:#172536;--muted:#637487;--line:#dce5ed;--soft:#f3f6f9;--white:#fff;--green:#18734b;--green-bg:#e8f5ee;--red:#a52a2a;--red-bg:#fff0ef;--amber:#875d08;--amber-bg:#fff7df;--shadow:0 18px 50px rgba(14,39,68,.1)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f5f7fa;color:var(--ink);font-size:14px}button,input,select{font:inherit}button,a,input,select{outline-offset:3px}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #8ec8f4}.hidden{display:none!important}.muted{color:var(--muted)}
.login-page{min-height:100dvh;display:grid;grid-template-columns:minmax(280px,1fr) minmax(380px,520px);background:var(--white)}.login-brand{padding:clamp(40px,8vw,110px);background:var(--navy);color:white;display:flex;flex-direction:column;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px;font-weight:760;letter-spacing:.01em}.brand-mark{width:42px;height:42px;border-radius:11px;background:#fff;color:var(--navy);display:grid;place-items:center;font-weight:850}.login-brand h1{font-size:clamp(38px,5vw,68px);line-height:1.02;max-width:720px;margin:70px 0 22px;letter-spacing:-.045em}.login-brand p{color:#c9d7e4;max-width:560px;font-size:16px;line-height:1.7}.login-panel{display:grid;place-items:center;padding:32px}.login-card{width:min(100%,380px)}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:11px;color:var(--blue);font-weight:760}.login-card h2{font-size:30px;margin:12px 0 8px;letter-spacing:-.03em}.login-card>p{margin:0 0 28px}.field{display:flex;flex-direction:column;gap:7px}.field label{font-size:12px;font-weight:700;color:#38495c}.field small{color:var(--muted);line-height:1.45}.form-stack{display:grid;gap:16px}.input,select{width:100%;min-height:44px;border:1px solid #cbd6df;border-radius:8px;background:#fff;color:var(--ink);padding:10px 12px}.input:hover,select:hover{border-color:#9eb0bf}.input:focus,select:focus{border-color:var(--blue)}
.btn{border:0;border-radius:8px;min-height:42px;padding:9px 15px;font-weight:720;cursor:pointer;background:var(--blue);color:#fff;display:inline-flex;align-items:center;justify-content:center;gap:7px}.btn:hover{background:var(--blue2)}.btn:disabled{opacity:.55;cursor:wait}.btn.secondary{background:#fff;color:var(--ink);border:1px solid #cbd6df}.btn.secondary:hover{background:var(--soft)}.btn.danger{background:var(--red)}.btn.ghost{background:transparent;color:#d8e6f3;border:1px solid #ffffff2e}.btn.small{min-height:34px;padding:6px 10px;font-size:12px}.error{color:var(--red);background:var(--red-bg);border:1px solid #f0c7c4;padding:10px 12px;border-radius:8px;line-height:1.4}.login-card .btn{width:100%;margin-top:5px}
.shell{min-height:100dvh;display:grid;grid-template-columns:245px minmax(0,1fr)}.side{background:var(--navy);color:#fff;padding:24px 18px;position:sticky;top:0;height:100dvh;display:flex;flex-direction:column}.side .brand{padding:0 8px 28px}.nav{display:grid;gap:4px}.nav button{border:0;background:transparent;color:#bdccda;text-align:left;padding:11px 12px;border-radius:8px;cursor:pointer;font-weight:650}.nav button:hover,.nav button.active{background:#ffffff14;color:#fff}.side-note{margin-top:auto;padding:16px 12px 0;border-top:1px solid #ffffff1c;color:#aebfd0;font-size:11px;line-height:1.6}.workspace{min-width:0}.topbar{height:74px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 clamp(18px,4vw,48px);position:sticky;top:0;z-index:5}.topbar h1{font-size:19px;margin:0;letter-spacing:-.02em}.topbar-right{display:flex;align-items:center;gap:12px}.health-dot{width:8px;height:8px;border-radius:50%;background:#29a36a;box-shadow:0 0 0 4px #29a36a1c}.content{max-width:1440px;padding:32px clamp(18px,4vw,48px) 60px}.view{display:none}.view.active{display:block}.page-head{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:22px}.page-head h2{font-size:28px;margin:0 0 7px;letter-spacing:-.035em}.page-head p{margin:0;color:var(--muted);line-height:1.55}.cards{display:grid;grid-template-columns:repeat(5,minmax(140px,1fr));gap:14px;margin-bottom:22px}.metric,.panel{background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:0 2px 10px rgba(14,39,68,.035)}.metric{padding:18px}.metric strong{display:block;font-size:27px;letter-spacing:-.04em;color:var(--navy);margin-bottom:4px}.metric span{font-size:12px;color:var(--muted)}.panel{padding:22px;margin-bottom:18px}.panel-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:18px}.panel-head h3{font-size:17px;margin:0 0 5px}.panel-head p{margin:0;color:var(--muted);font-size:12px;line-height:1.5}.form-grid{display:grid;grid-template-columns:repeat(4,minmax(155px,1fr));gap:14px}.form-actions{display:flex;align-items:center;gap:9px;margin-top:18px}.hint{margin-top:14px;padding:12px 14px;background:var(--soft);border-radius:8px;color:#53677a;font-size:12px;line-height:1.55}.toolbar{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.toolbar .input,.toolbar select{width:auto;min-width:190px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:9px}table{width:100%;border-collapse:collapse;min-width:780px}th{text-align:left;background:#f7f9fb;color:#5d6f81;text-transform:uppercase;letter-spacing:.07em;font-size:10px;padding:11px 13px;border-bottom:1px solid var(--line)}td{padding:13px;border-bottom:1px solid #e8eef3;vertical-align:middle}tr:last-child td{border-bottom:0}.ref{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:11px;color:#34485c}.actions{display:flex;gap:6px;flex-wrap:wrap}.badge{display:inline-flex;align-items:center;border-radius:999px;padding:4px 9px;font-size:10px;font-weight:750;text-transform:uppercase;letter-spacing:.04em;background:var(--green-bg);color:var(--green)}.badge.off,.badge.cancelled{background:var(--red-bg);color:var(--red)}.badge.info{background:#e9f2fb;color:var(--blue)}.empty{text-align:center;padding:38px 20px;color:var(--muted)}.empty strong{display:block;color:var(--ink);margin-bottom:6px}.system-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.system-item{border:1px solid var(--line);padding:16px;border-radius:9px}.system-item span{display:block;color:var(--muted);font-size:11px;margin-bottom:6px}.system-item strong{font-size:14px}.toast{position:fixed;right:24px;bottom:24px;z-index:30;max-width:390px;background:var(--navy);color:#fff;padding:13px 16px;border-radius:9px;box-shadow:var(--shadow);line-height:1.45}.toast.bad{background:#8d2525}dialog{border:0;border-radius:13px;padding:0;width:min(680px,calc(100vw - 28px));box-shadow:var(--shadow);color:var(--ink)}dialog::backdrop{background:#07192a99}.dialog-head{display:flex;justify-content:space-between;align-items:center;padding:19px 22px;border-bottom:1px solid var(--line)}.dialog-head h3{margin:0}.dialog-body{padding:22px;max-height:70dvh;overflow:auto}.dialog-foot{display:flex;justify-content:flex-end;gap:8px;padding:16px 22px;border-top:1px solid var(--line)}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.detail{background:var(--soft);padding:12px;border-radius:8px}.detail span{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.07em;margin-bottom:5px}.timeline{border-left:2px solid var(--line);margin:12px 0 0 7px;padding-left:18px}.event{position:relative;margin:0 0 17px}.event:before{content:"";position:absolute;width:8px;height:8px;border-radius:50%;background:var(--blue);left:-23px;top:5px}.event small{color:var(--muted)}
@media(max-width:1050px){.cards{grid-template-columns:repeat(3,1fr)}.form-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.login-page{grid-template-columns:1fr}.login-brand{display:none}.shell{grid-template-columns:1fr}.side{height:auto;position:static;padding:14px 16px}.side .brand,.side-note{display:none}.nav{display:flex;overflow:auto}.nav button{white-space:nowrap}.topbar{top:62px;height:64px}.topbar .health-label{display:none}.content{padding-top:22px}.cards{grid-template-columns:repeat(2,1fr)}.form-grid,.system-grid,.detail-grid{grid-template-columns:1fr}.page-head{flex-direction:column}.panel{padding:17px}.toolbar .input,.toolbar select{width:100%}.toast{left:14px;right:14px;bottom:14px}}@media(max-width:420px){.cards{grid-template-columns:1fr 1fr}.metric{padding:14px}.metric strong{font-size:23px}}
</style></head><body><div id="app"></div><div id="toast" class="toast hidden" role="status" aria-live="polite"></div>
<dialog id="detailDialog"><div class="dialog-head"><h3>Booking details</h3><button class="btn secondary small" onclick="closeDialog('detailDialog')" aria-label="Close booking details">Close</button></div><div class="dialog-body" id="detailBody"></div></dialog>
<dialog id="moveDialog"><form onsubmit="submitMove(event)"><div class="dialog-head"><h3>Reschedule session</h3><button type="button" class="btn secondary small" onclick="closeDialog('moveDialog')">Close</button></div><div class="dialog-body form-stack"><p class="muted">Choose a new start and end in America/Chicago. The session duration must remain unchanged and configured capacity must be available.</p><input id="moveRef" type="hidden"><div class="field"><label for="moveStart">New start</label><input class="input" id="moveStart" type="datetime-local" required></div><div class="field"><label for="moveEnd">New end</label><input class="input" id="moveEnd" type="datetime-local" required></div></div><div class="dialog-foot"><button type="button" class="btn secondary" onclick="closeDialog('moveDialog')">Cancel</button><button class="btn" type="submit">Check and reschedule</button></div></form></dialog>
<script>
const A=document.querySelector('#app'),T=document.querySelector('#toast');let csrf='',services=[],editingRule=null;
const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function notice(msg,bad=false){T.textContent=msg;T.className='toast'+(bad?' bad':'');clearTimeout(notice.t);notice.t=setTimeout(()=>T.classList.add('hidden'),4500)}
async function api(path,opt={}){opt.headers={'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{}),...(opt.headers||{})};let r=await fetch(path,opt),j;try{j=await r.json()}catch{j={error:'Unexpected server response'}}if(r.status===401&&path!='/admin/api/login'){showLogin(document.querySelector('.shell')?'Your session expired. Please sign in again.':'');throw Error('Session expired')}if(!r.ok)throw Error(j.error||'Request failed');return j}
function showLogin(message=''){csrf='';A.innerHTML=`<main class="login-page"><section class="login-brand"><div class="brand"><span class="brand-mark">BDS</span><span>Best Driving School</span></div><div><p class="eyebrow" style="color:#9ec8e7">Calendar operations</p><h1>Clear schedules.<br>Confident service.</h1><p>Private staff access for availability, blackouts and appointment management.</p></div><small>America/Chicago · Internal calendar</small></section><section class="login-panel"><form class="login-card form-stack" onsubmit="doLogin(event)"><div><p class="eyebrow">Staff portal</p><h2>Welcome back</h2><p class="muted">Sign in with your calendar administrator account.</p></div><div class="field"><label for="loginUser">Username</label><input class="input" id="loginUser" autocomplete="username" required autofocus></div><div class="field"><label for="loginPass">Password</label><input class="input" id="loginPass" type="password" autocomplete="current-password" required></div><p id="loginError" class="error ${message?'':'hidden'}">${esc(message)}</p><button id="loginButton" class="btn" type="submit">Sign in securely</button></form></section></main>`}
async function doLogin(e){e.preventDefault();let b=document.querySelector('#loginButton'),err=document.querySelector('#loginError');b.disabled=true;b.textContent='Signing in…';err.classList.add('hidden');try{let j=await api('/admin/api/login',{method:'POST',body:JSON.stringify({username:loginUser.value,password:loginPass.value})});csrf=j.csrf;await showApp()}catch(x){err.textContent=x.message==='Unauthorized'?'Username or password is incorrect.':x.message;err.classList.remove('hidden');b.disabled=false;b.textContent='Sign in securely'}}
function shell(){A.innerHTML=`<div class="shell"><aside class="side"><div class="brand"><span class="brand-mark">BDS</span><span>Calendar Admin</span></div><nav class="nav" aria-label="Admin sections">${[['overview','Overview'],['availability','Availability'],['blackouts','Blackouts'],['bookings','Bookings'],['system','System status']].map(([id,label],i)=>`<button class="${i?'':'active'}" data-view="${id}" onclick="view('${id}',this)">${label}</button>`).join('')}</nav><div class="side-note">Internal provider<br>America/Chicago</div></aside><div class="workspace"><header class="topbar"><h1 id="viewTitle">Overview</h1><div class="topbar-right"><span class="health-dot"></span><span class="health-label muted">System operational</span><button class="btn secondary small" onclick="logout()">Log out</button></div></header><main class="content">
<section id="overview" class="view active"><div class="page-head"><div><h2>Calendar overview</h2><p>Live operational totals from the internal booking database.</p></div><button class="btn secondary" onclick="refreshAll()">Refresh</button></div><div class="cards" id="metrics"></div><div class="panel"><div class="panel-head"><div><h3>Upcoming schedule</h3><p>The next accepted sessions in chronological order.</p></div></div><div id="upcomingTable"></div></div></section>
<section id="availability" class="view"><div class="page-head"><div><h2>Availability</h2><p>Create recurring windows with explicit positive capacity. Times use America/Chicago.</p></div></div><div class="panel"><div class="panel-head"><div><h3 id="ruleTitle">Create availability rule</h3><p>Choose a canonical service. The calendar derives session duration from its verified plan.</p></div></div><form id="ruleForm" onsubmit="saveRule(event)"><div class="form-grid"><div class="field"><label for="ruleService">Service</label><select id="ruleService" required onchange="serviceHint()"></select></div><div class="field"><label for="ruleDay">Day of week</label><select id="ruleDay" required>${days.map((d,i)=>`<option value="${i}">${d}</option>`).join('')}</select></div><div class="field"><label for="ruleStart">Start time</label><input class="input" id="ruleStart" type="time" required></div><div class="field"><label for="ruleEnd">End time</label><input class="input" id="ruleEnd" type="time" required></div><div class="field"><label for="ruleFrom">Effective from</label><input class="input" id="ruleFrom" type="date" required></div><div class="field"><label for="ruleUntil">Effective until</label><input class="input" id="ruleUntil" type="date"><small>Optional</small></div><div class="field"><label for="ruleCapacity">Capacity</label><input class="input" id="ruleCapacity" type="number" min="1" max="100" step="1" required><small>Simultaneous accepted sessions</small></div></div><div id="serviceHint" class="hint"></div><div class="form-actions"><button class="btn" id="ruleSubmit">Create active rule</button><button class="btn secondary hidden" id="ruleCancel" type="button" onclick="cancelRuleEdit()">Cancel edit</button></div></form></div><div class="panel"><div class="panel-head"><div><h3>Configured rules</h3><p>Disabled rules remain visible for audit and can be reactivated.</p></div></div><div id="rulesTable"></div></div></section>
<section id="blackouts" class="view"><div class="page-head"><div><h2>Blackouts</h2><p>Close all services or one service for an exact America/Chicago interval.</p></div></div><div class="panel"><form id="blackoutForm" onsubmit="saveBlackout(event)"><div class="form-grid"><div class="field"><label for="blackoutService">Service</label><select id="blackoutService" required></select></div><div class="field"><label for="blackoutStart">Start</label><input class="input" id="blackoutStart" type="datetime-local" required></div><div class="field"><label for="blackoutEnd">End</label><input class="input" id="blackoutEnd" type="datetime-local" required></div><div class="field"><label for="blackoutNote">Reason</label><input class="input" id="blackoutNote" maxlength="300" placeholder="Optional staff note"></div></div><div class="form-actions"><button class="btn">Add active blackout</button></div></form></div><div class="panel"><div class="panel-head"><div><h3>Blackout periods</h3><p>Blackouts override availability while active.</p></div></div><div id="blackoutsTable"></div></div></section>
<section id="bookings" class="view"><div class="page-head"><div><h2>Bookings</h2><p>Sessions, group context and operational history.</p></div></div><div class="panel"><div class="toolbar"><input class="input" id="bookingSearch" placeholder="Search name, email, service or reference"><select id="bookingStatus"><option value="">All statuses</option><option value="accepted">Accepted</option><option value="cancelled">Cancelled</option></select><button class="btn" onclick="loadBookings()">Apply filters</button><button class="btn secondary" onclick="clearBookingFilters()">Clear</button></div></div><div class="panel"><div id="bookingsTable"></div></div></section>
<section id="system" class="view"><div class="page-head"><div><h2>System status</h2><p>Safe deployment information for staff diagnostics.</p></div></div><div class="panel"><div class="system-grid"><div class="system-item"><span>Calendar provider</span><strong>Internal</strong></div><div class="system-item"><span>Business timezone</span><strong>America/Chicago</strong></div><div class="system-item"><span>Health</span><strong style="color:var(--green)">Operational</strong></div></div><div class="hint">Availability starts empty by design. Retell can offer only slots generated from active rules with positive capacity. Credentials and database internals are never displayed here.</div></div></section>
</main></div></div>`}
async function showApp(){shell();try{let [summary,svc]=await Promise.all([api('/admin/api/summary'),api('/admin/api/services')]);csrf=summary.csrf;services=svc.items;fillServices();renderMetrics(summary);await Promise.all([loadRules(),loadBlackouts(),loadBookings()])}catch(x){if(x.message!=='Session expired')notice(x.message,true)}}
function view(id,btn){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');viewTitle.textContent=btn.textContent;window.scrollTo({top:0,behavior:'smooth'})}
function fillServices(){let opts=services.map(s=>`<option value="${esc(s.package_id)}">${esc(s.name)} · ${s.session_plan.join(' + ')} min</option>`).join('');ruleService.innerHTML=opts;blackoutService.innerHTML='<option value="*">All services</option>'+opts;serviceHint()}
function serviceHint(){let s=services.find(x=>x.package_id===ruleService.value);const serviceHintEl=document.querySelector('#serviceHint');serviceHintEl.innerHTML=s?`<strong>${esc(s.name)}</strong> · Required session plan: ${s.session_plan.map(x=>`${x} minutes`).join(' + ')}. The window must fit at least one ${Math.min(...s.session_plan)}-minute session.`:'Select a service to see its session plan.'}
function renderMetrics(d){metrics.innerHTML=[['Active bookings',d.active],['Upcoming sessions',d.upcoming],['Cancelled sessions',d.cancelled],['Active rules',d.rules],['Active blackouts',d.blackouts]].map(([l,n])=>`<div class="metric"><strong>${n}</strong><span>${l}</span></div>`).join('')}
function empty(title,body){return `<div class="empty"><strong>${esc(title)}</strong>${esc(body)}</div>`}
function badge(active,label){return `<span class="badge ${active?'':'off'}">${esc(label)}</span>`}
function localTime(v){if(!v)return '—';return new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',dateStyle:'medium',timeStyle:'short'}).format(new Date(v))+' CT'}
function serviceName(id){return services.find(s=>s.package_id===id)?.name||id}
async function refreshAll(){try{let d=await api('/admin/api/summary');csrf=d.csrf;renderMetrics(d);await Promise.all([loadRules(),loadBlackouts(),loadBookings()]);notice('Dashboard refreshed.')}catch(x){notice(x.message,true)}}
async function loadRules(){let d=await api('/admin/api/availability');rulesTable.innerHTML=d.items.length?`<div class="table-wrap"><table><thead><tr><th>Service</th><th>Day</th><th>Window</th><th>Effective dates</th><th>Capacity</th><th>Status</th><th>Actions</th></tr></thead><tbody>${d.items.map(x=>`<tr><td><strong>${esc(serviceName(x.package_id))}</strong><br><span class="ref">${esc(x.package_id)}</span></td><td>${days[x.weekday]}</td><td>${esc(x.start_time)}–${esc(x.end_time)} CT</td><td>${esc(x.effective_start)} → ${esc(x.effective_end||'No end date')}</td><td>${x.capacity}</td><td>${badge(x.active===1,x.active===1?'Active':'Disabled')}</td><td><div class="actions">${x.active===1?`<button class="btn secondary small" onclick="beginRuleEdit('${x.id}','${x.start_time}','${x.end_time}',${x.capacity})">Edit</button><button class="btn danger small" onclick="toggleItem('availability','${x.id}',false)">Disable</button>`:`<button class="btn secondary small" onclick="toggleItem('availability','${x.id}',true)">Activate</button>`}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No availability rules','Create the first explicit positive-capacity rule above.')}
async function saveRule(e){e.preventDefault();let payload={package_id:ruleService.value,weekday:+ruleDay.value,start_time:ruleStart.value,end_time:ruleEnd.value,effective_start:ruleFrom.value,effective_end:ruleUntil.value||null,capacity:+ruleCapacity.value};try{if(editingRule)await api('/admin/api/availability/'+editingRule,{method:'POST',body:JSON.stringify({start_time:payload.start_time,end_time:payload.end_time,capacity:payload.capacity})});else await api('/admin/api/availability',{method:'POST',body:JSON.stringify(payload)});notice(editingRule?'Availability rule updated.':'Availability rule created.');cancelRuleEdit();await refreshAll()}catch(x){notice(x.message,true)}}
function beginRuleEdit(id,s,e,c){editingRule=id;ruleTitle.textContent='Edit availability rule';ruleStart.value=s;ruleEnd.value=e;ruleCapacity.value=c;ruleService.disabled=ruleDay.disabled=ruleFrom.disabled=ruleUntil.disabled=true;ruleSubmit.textContent='Save changes';ruleCancel.classList.remove('hidden');document.querySelector('#availability').scrollIntoView({behavior:'smooth'})}
function cancelRuleEdit(){editingRule=null;if(!document.querySelector('#ruleForm'))return;ruleForm.reset();ruleService.disabled=ruleDay.disabled=ruleFrom.disabled=ruleUntil.disabled=false;ruleTitle.textContent='Create availability rule';ruleSubmit.textContent='Create active rule';ruleCancel.classList.add('hidden');serviceHint()}
async function toggleItem(type,id,activate){let verb=activate?'activate':'disable';if(!confirm(`Are you sure you want to ${verb} this ${type==='availability'?'availability rule':'blackout'}?`))return;try{await api(`/admin/api/${type}/${id}/${activate?'activate':'deactivate'}`,{method:'POST',body:'{}'});notice(`Item ${activate?'activated':'disabled'}.`);await refreshAll()}catch(x){notice(x.message,true)}}
async function loadBlackouts(){let d=await api('/admin/api/blackouts');blackoutsTable.innerHTML=d.items.length?`<div class="table-wrap"><table><thead><tr><th>Service</th><th>Starts</th><th>Ends</th><th>Reason</th><th>Status</th><th>Action</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${esc(x.package_id==='*'?'All services':serviceName(x.package_id))}</td><td>${localTime(x.start)}</td><td>${localTime(x.end)}</td><td>${esc(x.note||'—')}</td><td>${badge(x.active===1,x.active===1?'Active':'Disabled')}</td><td>${x.active===1?`<button class="btn danger small" onclick="toggleItem('blackouts','${x.id}',false)">Disable</button>`:`<button class="btn secondary small" onclick="toggleItem('blackouts','${x.id}',true)">Activate</button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('No blackouts','No closure periods are configured.')}
async function saveBlackout(e){e.preventDefault();if(blackoutStart.value>=blackoutEnd.value){notice('Blackout end must be after its start.',true);return}try{await api('/admin/api/blackouts',{method:'POST',body:JSON.stringify({package_id:blackoutService.value,start:blackoutStart.value,end:blackoutEnd.value,note:blackoutNote.value})});blackoutForm.reset();notice('Blackout added.');await refreshAll()}catch(x){notice(x.message,true)}}
async function loadBookings(){let q=encodeURIComponent(bookingSearch?.value||''),s=encodeURIComponent(bookingStatus?.value||''),d=await api(`/admin/api/bookings?q=${q}&status=${s}`);if(document.querySelector('#upcomingTable')){let up=d.items.filter(x=>x.status==='accepted'&&new Date(x.start)>=new Date()).slice(0,8);upcomingTable.innerHTML=bookingTable(up,false)}bookingsTable.innerHTML=bookingTable(d.items,true)}
function bookingTable(items,actions){if(!items.length)return empty('No bookings found','Bookings will appear here after a confirmed API create.');return `<div class="table-wrap"><table><thead><tr><th>Appointment</th><th>Customer</th><th>Service</th><th>Session</th><th>Time</th><th>Status</th>${actions?'<th>Actions</th>':''}</tr></thead><tbody>${items.map(x=>`<tr><td class="ref">${esc(x.appointment_ref)}</td><td>${esc(x.customer_name)}</td><td>${esc(serviceName(x.package_id))}<br><span class="ref">${esc(x.group_id)}</span></td><td>${x.session_index||'—'}</td><td>${localTime(x.start)}<br><span class="muted">to ${localTime(x.end)}</span></td><td><span class="badge ${x.status==='cancelled'?'cancelled':''}">${esc(x.status)}</span></td>${actions?`<td><div class="actions"><button class="btn secondary small" onclick="showDetail('${x.appointment_ref}')">Details</button>${x.status==='accepted'?`<button class="btn secondary small" onclick="openMove('${x.appointment_ref}')">Reschedule</button><button class="btn danger small" onclick="cancelBooking('${x.appointment_ref}')">Cancel</button>`:''}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`}
function clearBookingFilters(){bookingSearch.value='';bookingStatus.value='';loadBookings()}
async function showDetail(ref){try{let d=await api('/admin/api/bookings/'+ref),b=d.booking;detailBody.innerHTML=`<div class="detail-grid"><div class="detail"><span>Appointment</span><strong class="ref">${esc(b.appointment_ref)}</strong></div><div class="detail"><span>Status</span>${badge(b.status==='accepted',b.status)}</div><div class="detail"><span>Customer</span><strong>${esc(b.customer_name)}</strong><br>${esc(b.customer_email)}</div><div class="detail"><span>Service</span><strong>${esc(serviceName(b.package_id))}</strong></div><div class="detail"><span>Group</span><strong class="ref">${esc(b.group_id)}</strong></div><div class="detail"><span>Current time</span><strong>${localTime(b.start)}</strong><br>${localTime(b.end)}</div></div><h4>Group sessions</h4>${bookingTable(d.group_sessions.map((x,i)=>({...x,customer_name:b.customer_name,package_id:b.package_id,group_id:b.group_id,session_index:i+1})),false)}<h4>History</h4><div class="timeline">${d.history.length?d.history.map(x=>`<div class="event"><strong>${esc(x.action.replaceAll('_',' '))}</strong><br><small>${localTime(x.at)}</small></div>`).join(''):'<p class="muted">No history events.</p>'}</div>`;detailDialog.showModal()}catch(x){notice(x.message,true)}}
function openMove(ref){moveRef.value=ref;moveStart.value='';moveEnd.value='';moveDialog.showModal()}
async function submitMove(e){e.preventDefault();if(moveStart.value>=moveEnd.value){notice('End must be after start.',true);return}try{await api('/admin/api/bookings/'+encodeURIComponent(moveRef.value)+'/reschedule',{method:'POST',body:JSON.stringify({start:moveStart.value,end:moveEnd.value})});closeDialog('moveDialog');notice('Session rescheduled.');await refreshAll()}catch(x){notice(x.message,true)}}
async function cancelBooking(ref){if(!confirm('Cancel this session? Its capacity will be released. This action does not issue a refund.'))return;try{await api('/admin/api/bookings/'+encodeURIComponent(ref)+'/cancel',{method:'POST',body:'{}'});notice('Session cancelled. No refund action was taken.');await refreshAll()}catch(x){notice(x.message,true)}}
function closeDialog(id){document.querySelector('#'+id).close()}
async function logout(){try{await api('/admin/api/logout',{method:'POST',body:'{}'})}catch{}showLogin()}
showApp().catch(()=>showLogin());
</script></body></html>'''
